package com.frazersan.overheadreminders;

import java.util.function.LongSupplier;

/** A monotonic deadline, polled on the client thread; no background timer threads. */
public class DeathChargeTimer
{
    private final LongSupplier clock;
    private boolean active;
    private long deadline;

    DeathChargeTimer()
    {
        this(System::nanoTime);
    }

    DeathChargeTimer(LongSupplier clock)
    {
        this.clock = clock;
    }

    public void start()
    {
        deadline = clock.getAsLong() + 60_000_000_000L;
        active = true;
    }

    public DeathChargeTimerState getState()
    {
        return !active ? DeathChargeTimerState.IDLE
            : clock.getAsLong() >= deadline ? DeathChargeTimerState.EXPIRED : DeathChargeTimerState.ACTIVE;
    }

    public void stop()
    {
        active = false;
    }
}

package com.frazersan.overheadreminders;

public enum DeathChargeTimerState
{
	IDLE,
	ACTIVE,
	EXPIRED,
}

package com.frazersan.overheadreminders;

/** Threshold latch: display expiry alone cannot rearm a low-prayer warning. */
final class LowPrayerState
{
    private boolean low;

    boolean update(int prayer, int threshold)
    {
        boolean next = prayer <= threshold;
        boolean alert = next && !low;
        low = next;
        return alert;
    }

    void reset()
    {
        low = false;
    }
}

package com.frazersan.overheadreminders;

import java.awt.Color;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.LongSupplier;
import javax.inject.Inject;
import javax.inject.Singleton;

/** One independently expiring entry per type. Duplicate events never extend its life. */
@Singleton
public class NotificationStore
{
    static final class Entry
    {
        final String key;
        final String message;
        final Color color;
        final long expiresAt;

        Entry(String key, String message, Color color, long expiresAt)
        {
            this.key = key;
            this.message = message;
            this.color = color;
            this.expiresAt = expiresAt;
        }

        String displayText(long now, boolean countdown)
        {
            return countdown ? message + " (" + Math.max(1, (expiresAt - now + 999_999_999L) / 1_000_000_000L) + "s)" : message;
        }
    }

    private final Map<String, Entry> entries = new LinkedHashMap<>();
    private final LongSupplier clock;

    @Inject
    public NotificationStore()
    {
        this(System::nanoTime);
    }

    NotificationStore(LongSupplier clock)
    {
        this.clock = clock;
    }

    synchronized void show(String key, String template, Color color, int seconds)
    {
        prune();
        if (template == null || template.trim().isEmpty())
        {
            entries.remove(key);
            return;
        }
        if (!entries.containsKey(key))
        {
            String message = template.replace("{0}", key).replaceAll("<[^>]*>", "")
                .replaceAll("[\r\n\t]+", " ").trim();
            if (!message.isEmpty())
            {
                entries.put(key, new Entry(key, message, color == null ? Color.WHITE : color,
                    clock.getAsLong() + Math.max(1, Math.min(120, seconds)) * 1_000_000_000L));
            }
        }
    }

    synchronized List<Entry> snapshot()
    {
        prune();
        return new ArrayList<>(entries.values());
    }

    long now()
    {
        return clock.getAsLong();
    }

    synchronized void remove(String key)
    {
        entries.remove(key);
    }

    synchronized void clear()
    {
        entries.clear();
    }

    private void prune()
    {
        long now = clock.getAsLong();
        entries.values().removeIf(entry -> now >= entry.expiresAt);
    }
}

